 internal static void SnapWindow(Form f,string side){var area=Screen.FromControl(f).WorkingArea;f.Bounds=new Rectangle(side=="right"?area.Right-f.Width:area.Left,area.Top,f.Width,Math.Min(f.Height,area.Height));}
 internal static void SnapNearEdge(Form f){var a=Screen.FromControl(f).WorkingArea;int x=f.Left,y=f.Top;if(Math.Abs(x-a.Left)<22)x=a.Left;if(Math.Abs(f.Right-a.Right)<22)x=a.Right-f.Width;if(Math.Abs(y-a.Top)<22)y=a.Top;if(Math.Abs(f.Bottom-a.Bottom)<22)y=a.Bottom-f.Height;f.Location=new Point(x,y);}
